/**
 * GuestActionErrorCode
 *
 * Stable discriminators for guest RSVP/checkout refusals (#905).
 *
 * The frontend branches on these to render a CTA ("Log in", "split your
 * purchase") instead of echoing the translated ``detail``. Renaming a value is a
 * breaking change; rewording the message is always safe.
 */
export type GuestActionErrorCode = 'guest_account_exists' | 'guest_cart_too_large';

/**
 * GuestActionErrorSchema
 *
 * Refusal body for a guest RSVP/checkout carrying a stable ``code`` (#905).
 *
 * ``detail`` is translated and must never be matched on; ``code`` is the
 * machine-readable discriminator the frontend keys on to render a proper CTA
 * (``guest_account_exists`` → "Log in", ``guest_cart_too_large`` → "log in or
 * split your purchase").
 */
export type GuestActionErrorSchema = {
    /**
     * Detail
     */
    detail: string;
    code: GuestActionErrorCode;
};

/**
 * GuestRSVPRequestSchema
 *
 * Guest RSVP payload: guest identity plus optional note.
 */
export type GuestRsvpRequestSchema = {
    /**
     * Email
     */
    email: string;
    /**
     * First Name
     *
     * Guest user's first name (optional)
     */
    first_name?: string;
    /**
     * Last Name
     *
     * Guest user's last name (optional)
     */
    last_name?: string;
    /**
     * Turnstile Token
     *
     * Cloudflare Turnstile token (`cf-turnstile-response`); required when bot protection is configured
     */
    turnstile_token?: string | null;
    /**
     * Note
     */
    note?: string;
};

/**
 * GuestCheckoutResponseSchema
 *
 * Combined response for guest checkout - either email confirmation or Stripe checkout.
 */
export type GuestCheckoutResponseSchema = {
    /**
     * Message
     *
     * Confirmation message (for non-online payments)
     */
    message?: string | null;
    /**
     * Checkout Url
     *
     * Stripe checkout URL (for online payment)
     */
    checkout_url?: string | null;
    /**
     * Tickets
     *
     * Created tickets (only present after guest email confirmation for free/offline payments)
     */
    tickets?: Array<UserTicketSchema>;
    /**
     * Reservation Id
     *
     * Reservation handle; POST it to the checkout-session endpoint to get the Stripe URL
     */
    reservation_id?: string | null;
    /**
     * Requires Payment
     *
     * True for online tiers: call the checkout-session endpoint next. False = already complete.
     */
    requires_payment?: boolean;
};

